import { CheckIcon, CopyIcon, XIcon } from '@advui/icons'
import { composeEventHandlers } from '@advui/utils'
import { type ReactNode, forwardRef, useContext, useState } from 'react'
import { AccessibilityInfo, type LayoutChangeEvent, Platform } from 'react-native'
import { type TamaguiElement, Text, View, isWeb } from 'tamagui/unstyled'
import { visuallyHidden } from '../../utils/visuallyHidden'
import { Button, type ButtonProps } from '../button/Button'
import { ButtonGroupContext } from '../button/groupContext'
import { IconButton } from '../icon-button/IconButton'
import { Tooltip } from '../tooltip/Tooltip'
import { useClipboard } from './clipboard'

export interface CopyButtonLabels {
  /** Name of the icon-only button, and its tooltip. Default: "Copy". */
  copy: string
  /** Shown and announced after copying. Default: "Copied". */
  copied: string
  /** Shown and announced when copying fails. Default: "Couldn’t copy". */
  failed: string
}

const defaultLabels: CopyButtonLabels = {
  copy: 'Copy',
  copied: 'Copied',
  failed: 'Couldn’t copy',
}

export interface CopyButtonProps extends Omit<
  ButtonProps,
  'children' | 'icon' | 'iconAfter' | 'size' | 'loading' | 'onPress' | 'onCopy'
> {
  /** The text to copy. */
  value: string
  /** A visible label, e.g. "Copy link". Without one it is an icon button with a tooltip. */
  children?: ReactNode
  size?: 'sm' | 'md' | 'lg'
  /** How long the copied (or failed) state shows, in ms. Default 2000. */
  timeout?: number
  /** Called with the text once it is on the clipboard. */
  onCopy?: (value: string) => void
  /** Called when the clipboard refuses the text, or there is none (see `setClipboard`). */
  onCopyError?: (error: unknown) => void
  /** Button name, tooltip and announcements, for translation. */
  labels?: Partial<CopyButtonLabels>
}

const systemConfirmsCopy = () => Platform.OS === 'android' && Platform.Version >= 33

const icons = { idle: <CopyIcon />, copied: <CheckIcon />, failed: <XIcon /> }

/**
 * Copies a value to the clipboard and confirms it: the icon turns into a check
 * and screen readers hear "Copied". Without children it is an icon button.
 */
export const CopyButton = forwardRef<TamaguiElement, CopyButtonProps>(function CopyButton(
  {
    value,
    children,
    size,
    variant,
    timeout = 2000,
    onCopy,
    onCopyError,
    labels: labelsProp,
    onLayout,
    ...props
  },
  ref,
) {
  const labels = { ...defaultLabels, ...labelsProp }
  const group = useContext(ButtonGroupContext)
  const { copy, status } = useClipboard({ timeout, onCopy, onError: onCopyError })
  const [message, setMessage] = useState({ text: '', count: 0 })
  const [labelWidth, setLabelWidth] = useState<number>()
  const result = status === 'idle' ? null : labels[status]

  const onPress = async () => {
    const copied = await copy(value)
    const next = copied ? labels.copied : labels.failed
    if (isWeb) setMessage((current) => ({ text: next, count: current.count + 1 }))
    // Android 13 and later confirm every copy themselves, and TalkBack reads it.
    else if (!(copied && systemConfirmsCopy())) AccessibilityInfo.announceForAccessibility(next)
  }

  // The icon button keeps its name while the result shows in the tooltip, so
  // the name still says what it does; the result is announced instead.
  const button =
    children == null ? (
      <Tooltip content={result ?? labels.copy}>
        <IconButton
          ref={ref}
          aria-label={labels.copy}
          size={size}
          variant={variant}
          icon={icons[status]}
          onPress={onPress}
          onLayout={onLayout}
          {...props}
        />
      </Tooltip>
    ) : (
      <Button
        ref={ref}
        size={size}
        // In a ButtonGroup, the group's variant.
        variant={variant ?? (group ? undefined : 'outline')}
        icon={icons[status]}
        onPress={onPress}
        onLayout={composeEventHandlers(onLayout, (event: LayoutChangeEvent) => {
          if (status === 'idle') setLabelWidth(event.nativeEvent.layout.width)
        })}
        // A shorter result ("Copied") keeps the label's width, so the buttons
        // beside it do not move (or wrap to another row) for two seconds.
        {...(result && labelWidth !== undefined && { minWidth: labelWidth })}
        {...props}
      >
        {result ?? children}
      </Button>
    )

  return (
    <>
      {button}
      {isWeb ? (
        <View role="status" aria-live="polite" {...visuallyHidden}>
          {message.text ? <Text key={message.count}>{message.text}</Text> : null}
        </View>
      ) : null}
    </>
  )
})

import { useCallback, useEffect, useRef, useState } from 'react'
import { isWeb } from 'tamagui/unstyled'

/** Writes text to the clipboard; throws (or rejects) when it cannot. */
export type WriteClipboard = (text: string) => Promise<unknown> | void

// Set once at app start; a module value (not context) so it also reaches
// buttons inside native portals (sheets, dialogs), which drop React context.
let appClipboard: WriteClipboard | undefined

/**
 * Registers the app's clipboard for every Copy Button and Code Block, e.g.
 * `setClipboard(Clipboard.setStringAsync)` with `expo-clipboard`. iOS and
 * Android need one; web uses the browser's clipboard unless one is set.
 */
export function setClipboard(write: WriteClipboard | undefined) {
  appClipboard = write
}

/** The fallback for pages the Clipboard API refuses, such as `http:` ones. */
function copyWithSelection(text: string) {
  const active = document.activeElement as HTMLElement | null
  const area = document.createElement('textarea')
  area.value = text
  area.setAttribute('readonly', '')
  area.setAttribute('aria-hidden', 'true')
  Object.assign(area.style, { position: 'fixed', top: '0', left: '0', opacity: '0' })
  document.body.append(area)
  area.focus({ preventScroll: true })
  area.select()
  const copied = document.execCommand('copy')
  area.remove()
  active?.focus({ preventScroll: true })
  if (!copied) throw new Error('The browser refused to copy.')
}

/** Copies text with the app's clipboard, or the browser's on web. */
export async function writeClipboard(text: string) {
  if (appClipboard) {
    await appClipboard(text)
    return
  }
  if (!isWeb) {
    throw new Error('No clipboard. Call setClipboard() at app start (e.g. with expo-clipboard).')
  }
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text)
      return
    } catch {
      // Refused (no permission, or the page is not focused); try the old way.
    }
  }
  copyWithSelection(text)
}

export type ClipboardStatus = 'idle' | 'copied' | 'failed'

export interface UseClipboardOptions {
  /** How long `status` stays `copied` or `failed`, in ms. Default 2000. */
  timeout?: number
  onCopy?: (text: string) => void
  onError?: (error: unknown) => void
}

let warned = false

/**
 * Copies text and reports how it went, for your own copy controls. `copy`
 * resolves to whether it worked; `status` is `copied` or `failed` for
 * `timeout` ms after.
 */
export function useClipboard({ timeout = 2000, onCopy, onError }: UseClipboardOptions = {}) {
  const [status, setStatus] = useState<ClipboardStatus>('idle')
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const mounted = useRef(true)
  // The latest callbacks, so `copy` keeps its identity across renders.
  const callbacks = useRef({ onCopy, onError })
  useEffect(() => {
    callbacks.current = { onCopy, onError }
  })

  useEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
      clearTimeout(timer.current)
    }
  }, [])

  const copy = useCallback(
    async (text: string) => {
      clearTimeout(timer.current)
      let copied = true
      try {
        await writeClipboard(text)
        callbacks.current.onCopy?.(text)
      } catch (error) {
        copied = false
        // A missing native clipboard is a setup mistake; say so once.
        if (!isWeb && !appClipboard && !warned) {
          warned = true
          console.warn((error as Error).message)
        }
        callbacks.current.onError?.(error)
      }
      if (!mounted.current) return copied
      setStatus(copied ? 'copied' : 'failed')
      timer.current = setTimeout(() => setStatus('idle'), timeout)
      return copied
    },
    [timeout],
  )

  return { copy, status }
}

