import { CopyButton, HStack, Text } from '@advui/core'

export default function CopyButtonBasic() {
  return (
    <HStack alignItems="center" gap="2">
      <Text mono>pnpm add @advui/core</Text>
      <CopyButton value="pnpm add @advui/core" labels={{ copy: 'Copy command' }} />
    </HStack>
  )
}

import { CopyButton, HStack } from '@advui/core'

export default function CopyButtonLabel() {
  return (
    <HStack flexWrap="wrap" gap="3">
      <CopyButton value="https://example.org/invite/7Hq2" labels={{ copied: 'Link copied' }}>
        Copy invite link
      </CopyButton>
      <CopyButton value="#A-2041" variant="secondary" size="sm">
        Copy order number
      </CopyButton>
    </HStack>
  )
}

import { CopyButton, Field, Input } from '@advui/core'

const apiKey = 'demo_7Hq2xT9k'

export default function CopyButtonInInput() {
  return (
    <Field label="API key" width="100%" maxWidth="80">
      <Input
        defaultValue={apiKey}
        readOnly
        trailing={<CopyButton size="sm" value={apiKey} labels={{ copy: 'Copy API key' }} />}
      />
    </Field>
  )
}

import { Button, toast, useClipboard } from '@advui/core'
import { CheckIcon, CodeIcon } from '@advui/icons'

const settings = { theme: 'dark', density: 'compact', locale: 'en-GB' }

export default function CopyButtonUseClipboard() {
  const { copy, status } = useClipboard()
  return (
    <Button
      variant="outline"
      icon={status === 'copied' ? <CheckIcon /> : <CodeIcon />}
      onPress={async () => {
        // A toast is announced, so screen reader users hear the result too.
        toast((await copy(JSON.stringify(settings, null, 2))) ? 'Settings copied' : 'Couldn’t copy')
      }}
    >
      Copy settings as JSON
    </Button>
  )
}
